package gr.dit.hua.Foodie.core.model;

import jakarta.persistence.*;

// A registered user of the system. Customers and owners are both stored here,
// and the role field tells them apart. Visitors are not stored (they are just not logged in).
@Entity
@Table(name = "foodie_user")
public class User {

    // Primary key, generated by the database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Unique, so no two users share a username
    @Column(name = "username", nullable = false, unique = true, length = 255)
    private String username;

    // Unique, so it can also identify the user at login
    @Column(name = "email", nullable = false, unique = true, length = 255)
    private String email;

    // BCrypt hash of the password. The plain password is never stored.
    @Column(name = "password_hash", nullable = false, length = 255)
    private String passwordHash;

    // Stored as text (CUSTOMER / OWNER) instead of a number, so the data
    // stays correct if the enum order changes later
    @Enumerated(EnumType.STRING)
    @Column(name = "role", nullable = false, length = 20)
    private Role role;

    // Required by JPA, not for our own use
    protected User() {
    }

    // The role is set only here and has no setter. Registration always passes
    // CUSTOMER, so a user cannot make themselves an owner.
    public User(String username, String email, String passwordHash, Role role) {
        this.username = username;
        this.email = email;
        this.passwordHash = passwordHash;
        this.role = role;
    }

    // getters
    public Long getId() { return id; }
    public String getUsername() { return username; }
    public String getEmail() { return email; }
    public String getPasswordHash() { return passwordHash; }
    public Role getRole() { return role; }
}